"use client";
import Image from "next/image";
import { useEffect, useState } from "react";
import type { LearningSnapshot, SourceUnit } from "@/lib/learning/types";
import { Readable } from "./read-aloud";
import { sourceLabel } from "@/lib/learning/source-label";

/** Original material is fetched from the server-owned source, never regenerated by AI. */
export function OriginalMaterial({ snapshot, originalUrl, sourceId }: { snapshot: LearningSnapshot; originalUrl?: string; sourceId?: string }) {
  const [selected, setSelected] = useState(sourceId || snapshot.material.units.find(unit => unit.transcription)?.id || snapshot.material.units[0].id);
  const [result, setResult] = useState<{ id: string; unit?: SourceUnit; error?: string }>();
  useEffect(() => {
    const controller = new AbortController();
    fetch(`/api/learning/source?id=${encodeURIComponent(selected)}`, { headers: { "x-material-fingerprint": snapshot.fingerprint }, cache: "no-store", signal: controller.signal })
      .then(async response => { if (!response.ok) throw new Error("The source is no longer available in this temporary session. You can still open your original file."); return await response.json() as SourceUnit; })
      .then(unit => { if (!controller.signal.aborted) setResult({ id: selected, unit }); })
      .catch(error => { if (!controller.signal.aborted) setResult({ id: selected, error: error instanceof Error ? error.message : "The source could not be opened." }); });
    return () => controller.abort();
  }, [selected, snapshot.fingerprint]);
  const current = result?.id === selected ? result : undefined;
  return <aside className="original-material" aria-label="Original source material">
    <p className="adapt-eyebrow">Original source · unchanged</p>
    {snapshot.material.units.length > 1 ? <><label htmlFor="original-source-unit">Source page or section</label><select id="original-source-unit" value={selected} onChange={event => setSelected(event.target.value)}>{snapshot.material.units.map(unit => <option key={unit.id} value={unit.id}>{sourceLabel(unit)}</option>)}</select></> : <h3>{sourceLabel(snapshot.material.units[0])}</h3>}
    <p className="source-provenance">{sourceLabel(snapshot.material.units.find(unit => unit.id === selected))}</p>
    {!current && <p role="status">Opening the original source…</p>}
    {current?.error && <p role="alert">{current.error}</p>}
    {current?.unit?.text && <Readable label={`Original source: ${sourceLabel(current.unit)}`} units={[current.unit.text]}><pre className="original-source-text">{current.unit.text}</pre></Readable>}
    {snapshot.material.kind === "image" && originalUrl && <Image src={originalUrl} alt="Your original uploaded learning image" width={1000} height={1000} unoptimized className="original-source-image" />}
    {snapshot.material.kind === "audio" && originalUrl && <><p id="audio-source-label">Original audio · playback is optional</p><audio aria-labelledby="audio-source-label" controls preload="none" src={originalUrl} className="original-source-audio" /></>}
    {current?.unit?.transcription && <p className="field-help">Machine transcription of this interval in the original audio. Words and technical details may be misheard; this is not a verified verbatim transcript.</p>}
    {current?.unit && !current.unit.text && (snapshot.material.kind === "audio" ? <p>Choose a timestamped transcript section above to read the spoken content. You do not need to play the audio.</p> : <p>The original visual source is available in your file. A text extraction is not available for this part; the adapted description is an AI interpretation.</p>)}
    {originalUrl && <a href={originalUrl + (current?.unit?.locator.kind === "pdf" ? `#page=${current.unit.locator.page}` : "")} target="_blank" rel="noreferrer">Open original {snapshot.material.kind === "pdf" ? "PDF" : "material"}</a>}
    {snapshot.material.kind === "pdf" && <p className="field-help">This text comes from the source page. For exact visual layout, equations or formatting, use the original PDF.</p>}
  </aside>;
}
